        config.flowIpcAutoRichTextEditorBehavior = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_RICH_TEXT_EDITOR_BEHAVIOR"] == "1"
        config.flowIpcAutoRichTextEditorEditing = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_RICH_TEXT_EDITOR_EDITING"] == "1"
        config.flowIpcAutoRichTextEditorTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_RICH_TEXT_EDITOR_THEME"] == "1"
        config.flowIpcAutoNativeClipboardRead = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_NATIVE_CLIPBOARD_READ"] == "1"
        config.flowIpcAutoButtonTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_BUTTON_THEME"] == "1"
        config.flowIpcAutoTextFieldTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_TEXT_FIELD_THEME"] == "1"
        config.flowIpcAutoSelectTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_SELECT_THEME"] == "1"
        config.flowIpcAutoComboBoxTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_COMBO_BOX_THEME"] == "1"
        config.flowIpcAutoDatePickerTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_DATE_PICKER_THEME"] == "1"
        config.flowIpcAutoMultiSelectComboBoxTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_MULTI_SELECT_COMBO_BOX_THEME"] == "1"
