        config.flowIpcAutoAvatarGroupTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_AVATAR_GROUP_THEME"] == "1"
        config.flowIpcAutoMessageInputTheme = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_MESSAGE_INPUT_THEME"] == "1"
