        config.flowIpcAutoLoginOverlayForgotPassword = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_LOGIN_OVERLAY_FORGOT_PASSWORD"] == "1"
        config.flowIpcAutoLoginOverlayLogin = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_LOGIN_OVERLAY_LOGIN"] == "1"
        config.flowIpcAutoLoginOverlayInvalidLogin = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_LOGIN_OVERLAY_INVALID_LOGIN"] == "1"
        config.flowIpcAutoLoginOverlayClose = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_LOGIN_OVERLAY_CLOSE"] == "1"
        config.flowIpcAutoLoginOverlayRecoveryLogin = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_LOGIN_OVERLAY_RECOVERY_LOGIN"] == "1"
        config.flowIpcAutoLoginOverlayServerReopen = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_LOGIN_OVERLAY_SERVER_REOPEN"] == "1"
        config.flowIpcAutoLoginOverlayShowError = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_FLOW_IPC_AUTO_LOGIN_OVERLAY_SHOW_ERROR"] == "1"
        config.flowIpcAutoLoginOverlayErrorA11y = config.flowIpcAutoLoginOverlayErrorA11y
