struct CapabilityManifest {
    let path: String
    let loaded: Bool
    let permissionMode: String
    let allowedCommands: Set<String>
    let parseError: String

    static func load(module: String) -> CapabilityManifest {
        let path = "\(module)/desktop-capabilities.json"
        guard FileManager.default.fileExists(atPath: path) else {
            return CapabilityManifest(path: path,
                                      loaded: false,
                                      permissionMode: "allow-all-dev",
                                      allowedCommands: [],
                                      parseError: "")
        }
        guard let data = FileManager.default.contents(atPath: path) else {
            return CapabilityManifest(path: path,
                                      loaded: true,
                                      permissionMode: "allow-all-dev",
                                      allowedCommands: [],
                                      parseError: "manifest-unreadable")
        }
        do {
            let json = try JSONSerialization.jsonObject(with: data)
            guard let object = json as? [String: Any] else {
                return CapabilityManifest(path: path,
                                          loaded: true,
                                          permissionMode: "allow-all-dev",
                                          allowedCommands: [],
                                          parseError: "manifest-root-not-object")
            }
            let permissionMode = object["permissionMode"] as? String ?? "allow-all-dev"
            let windows = object["windows"] as? [[String: Any]] ?? []
            var commands = Set<String>()
            for window in windows where (window["label"] as? String ?? "main") == "main" {
                if let values = window["commands"] as? [String] {
                    commands.formUnion(values)
                }
                if let values = window["capabilities"] as? [String] {
                    commands.formUnion(values)
                }
            }
            return CapabilityManifest(path: path,
                                      loaded: true,
                                      permissionMode: permissionMode,
                                      allowedCommands: commands,
                                      parseError: "")
        } catch {
            return CapabilityManifest(path: path,
                                      loaded: true,
                                      permissionMode: "allow-all-dev",
                                      allowedCommands: [],
                                      parseError: error.localizedDescription)
        }
    }

    func allows(_ command: String) -> Bool {
        if permissionMode == "trace-only-dry-run" {
            return true
        }
        if !parseError.isEmpty {
            return false
        }
        if permissionMode == "manifest-enforced" {
            return loaded && allowedCommands.contains(command)
        }
        if !loaded {
            return true
        }
        return allowedCommands.contains(command)
    }

    func denialReason(_ command: String) -> String {
        if !parseError.isEmpty {
            return "manifest-invalid"
        }
        if permissionMode == "manifest-enforced" && !loaded {
            return "manifest-missing"
        }
        if loaded && !allowedCommands.contains(command) {
            return "manifest-denied"
        }
        return "unsupported-command"
    }

    func allowedReason(_ command: String) -> String {
        if permissionMode == "trace-only-dry-run" {
            if loaded && !allowedCommands.contains(command) {
                return "dry-run-would-deny"
            }
            return loaded ? "dry-run-manifest-allow" : "dry-run-development-default"
        }
        return loaded ? "manifest-allow" : "development-default"
    }

    func tracePayload() -> [String: Any] {
        [
            "path": path,
            "loaded": loaded,
            "permissionMode": permissionMode,
            "allowedCommands": allowedCommands.sorted(),
            "parseError": parseError
        ]
    }
}

func nowMillis() -> Int64 {
    Int64(Date().timeIntervalSince1970 * 1000)
}

extension String {
    var isBlank: Bool {
        trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }
}

func trace(_ direction: String, _ type: String, _ payload: [String: Any]) {
    let object: [String: Any] = [
        "direction": direction,
        "type": type,
        "at": nowMillis(),
        "payload": payload
    ]
    if let data = try? JSONSerialization.data(withJSONObject: object, options: []),
       let text = String(data: data, encoding: .utf8) {
        print("HOST_PROTOCOL \(text)")
    } else {
        print("HOST_PROTOCOL {\"direction\":\"\(direction)\",\"type\":\"\(type)\",\"at\":\(nowMillis()),\"payload\":{}}")
    }
    fflush(stdout)
}

func compactResourceLoadTrace(_ payload: [String: Any]) -> [String: Any] {
    let scalarKeys: Set<String> = [
        "frontendResourceSchemeVersion",
        "frontendResourceSchemeName",
        "frontendResourceLoaderMode",
        "stagingMode",
        "frontendResourceSchemeHandlerInstalled",
        "frontendResourceSchemeRequestObserved",
        "frontendResourceSchemeResponseObserved",
        "frontendResourceLoaderNoLocalhost",
        "frontendResourceFileBacked",
        "requestId",
        "resourceUrl",
        "resourceUrlPath",
        "sourcePath",
        "stagedUrl",
        "artifactFamily",
        "moduleSpecifier",
        "mimeType",
        "bytes",
        "sha256",
        "cacheStatus",
        "relativeImportBase",
        "resourceBaseUrl",
        "cleanupPolicy",
        "filePathRedacted",
        "fileDirectoryRedacted",
        "noLocalhostProof",
        "executionStatus",
        "failureLayer",
        "browserError",
        "error"
    ]
    let scalarPrefixes = [
        "productionBundleRuntimeOwner",
        "packagedFrontend",
        "frontendResolver",
        "frontendPipelineClosure",
        "generatedLazy",
        "currentAppFrontendBuild",
        "currentAppBuildFrontend",
        "currentAppGenerated",
        "currentAppProduction",
        "broaderComponentResourceMatrix",
        "dataComponentResourceMatrix",
        "gridLazyDataProvider",
        "gridScrollVirtualization",
        "inputComponentParityMatrix",
        "multiValueNavigationDisclosureMatrix",
        "overlayContextMenuMatrix",
        "contentAppShellLoginMatrix",
        "richTextEditorMatrix",
        "richTextEditorBehaviorMatrix",
        "richTextEditorEditingMatrix"
    ]
    var compact: [String: Any] = [:]
    for (key, value) in payload {
        let keep = scalarKeys.contains(key)
            || scalarPrefixes.contains { key.hasPrefix($0) }
        if !keep {
            continue
        }
        if let text = value as? String {
            compact[key] = text.count <= 512
                ? text
                : String(text.prefix(512)) + "...[truncated]"
        } else if let number = value as? NSNumber {
            compact[key] = number
        } else if let bool = value as? Bool {
            compact[key] = bool
        } else if let int = value as? Int {
            compact[key] = int
        } else if let int64 = value as? Int64 {
            compact[key] = int64
        } else if let double = value as? Double {
            compact[key] = double
        }
    }
    return compact
}

func compactTraceString(_ text: String, maxLength: Int = 1024) -> String {
    text.count <= maxLength
        ? text
        : String(text.prefix(maxLength)) + "...[truncated]"
}

func compactScalarTracePayload(_ payload: [String: Any],
                               maxStringLength: Int = 1024) -> [String: Any] {
    var compact: [String: Any] = [:]
    for (key, value) in payload {
        if let text = value as? String {
            compact[key] = compactTraceString(text, maxLength: maxStringLength)
        } else if let bool = value as? Bool {
            compact[key] = bool
        } else if let number = value as? NSNumber {
            compact[key] = number
        } else if let int = value as? Int {
            compact[key] = int
        } else if let int64 = value as? Int64 {
            compact[key] = int64
        } else if let double = value as? Double {
            compact[key] = double
        } else if let strings = value as? [String] {
            compact[key] = compactTraceString(strings.joined(separator: ","), maxLength: maxStringLength)
        } else if let numbers = value as? [NSNumber] {
            compact[key] = numbers.map { "\($0)" }.joined(separator: ",")
        }
    }
    return compact
}

