        if let text = value as? String {
            if alwaysKeep.contains(key) || keepDiagnostic || !text.isEmpty {
                compact[key] = compactTraceString(text, maxLength: 1024)
            }
        } else if let bool = value as? Bool {
            if bool || alwaysKeep.contains(key) || keepDiagnostic || key.hasSuffix("FixtureSubstituted") {
                compact[key] = bool
            }
        } else if let number = value as? NSNumber {
            let doubleValue = number.doubleValue
            if alwaysKeep.contains(key) || keepDiagnostic || (doubleValue != 0 && doubleValue != -1) {
                compact[key] = number
            }
        } else if let int = value as? Int {
            if alwaysKeep.contains(key) || keepDiagnostic || (int != 0 && int != -1) {
                compact[key] = int
            }
        } else if let int64 = value as? Int64 {
            if alwaysKeep.contains(key) || keepDiagnostic || (int64 != 0 && int64 != -1) {
                compact[key] = int64
            }
        } else if let double = value as? Double {
            if alwaysKeep.contains(key) || keepDiagnostic || (double != 0 && double != -1) {
                compact[key] = double
            }
        } else if let strings = value as? [String], !strings.isEmpty {
            compact[key] = compactTraceString(strings.joined(separator: ","), maxLength: 1024)
        } else if let numbers = value as? [NSNumber], !numbers.isEmpty {
            compact[key] = numbers.map { "\($0)" }.joined(separator: ",")
        }
    }
    return compact
}

func compactFlowIpcTracePayload(_ payload: [String: Any],
                                maxStringLength: Int = 1024) -> [String: Any] {
    let scalarKeys: Set<String> = [
        "requestId",
        "correlationId",
        "route",
        "sessionId",
        "uiId",
        "transport",
        "compatibilityMode",
        "serverSequence",
        "serverSequenceScope",
        "resourceUrl",
        "resourceUrlPath",
        "sourcePath",
        "path",
        "method",
        "status",
        "statusCode",
        "mimeType",
        "contentType",
        "bytes",
        "sha256",
        "range",
        "bodyPreview",
        "bodyBytes",
        "bodyRedacted",
        "fileName",
        "failureLayer",
        "nextResolutionStep",
        "noLocalhostProof"
    ]
    let prefixes = [
        "frontendResource",
        "frontendResolver",
        "frontendPipelineClosure",
        "packagedFrontend",
        "packagingFrontendInventory",
        "packagingRuntimeHandoffReuse",
        "generatedLazy",
        "generatedLoadOnDemand",
        "loadOnDemand",
        "currentApp",
        "productionBundleRuntimeOwner",
        "componentProductionOwner",
        "broaderComponentResourceMatrix",
        "dataComponentResourceMatrix",
        "gridLazyDataProvider",
        "gridScrollVirtualization",
        "inputComponentParityMatrix",
        "multiValueNavigationDisclosureMatrix",
        "overlayContextMenuMatrix",
        "contentAppShellLoginMatrix",
        "richTextEditorMatrix",
        "richTextEditorBehaviorMatrix",
        "richTextEditorEditingMatrix",
        "streamResource",
        "uploadReceiver",
        "uploadMultipart",
        "downloadHandlerSaveOpen",
        "frameworkStreamResource",
        "frameworkUpload",
        "frameworkDownloadHandler"
    ]
    var compact: [String: Any] = [:]
    for (key, value) in payload {
        let keep = scalarKeys.contains(key) || prefixes.contains { key.hasPrefix($0) }
        if !keep {
            continue
        }
        if let text = value as? String {
            if !text.isEmpty || key.hasSuffix("UnresolvedSpecifiers") {
                compact[key] = compactTraceString(text, maxLength: maxStringLength)
            }
        } else if let bool = value as? Bool {
            if bool || key.hasSuffix("FixtureSubstituted") || key.hasSuffix("FullBodyOmitted") {
                compact[key] = bool
            }
        } else if let number = value as? NSNumber {
            let doubleValue = number.doubleValue
            if doubleValue != 0 && doubleValue != -1 {
                compact[key] = number
            }
        } else if let int = value as? Int {
            if int != 0 && int != -1 {
                compact[key] = int
            }
        } else if let int64 = value as? Int64 {
            if int64 != 0 && int64 != -1 {
                compact[key] = int64
            }
        } else if let double = value as? Double {
            if double != 0 && double != -1 {
                compact[key] = double
            }
        } else if let strings = value as? [String], !strings.isEmpty {
            compact[key] = compactTraceString(strings.joined(separator: ","), maxLength: maxStringLength)
        }
    }
    return compact
}

func compactResourceManifestPayload(_ payload: [String: Any]) -> [String: Any] {
    var compact = compactFlowIpcTracePayload(payload, maxStringLength: 1024)
    if let artifactFamilies = payload["artifactFamilies"] as? [String], !artifactFamilies.isEmpty {
        compact["artifactFamilies"] = artifactFamilies.joined(separator: ",")
    }
    if let resources = payload["resources"] as? [[String: Any]] {
        var paths: [String] = []
        var families = Set<String>()
        var ipcAugmented = false
        for resource in resources {
            if let path = resource["path"] as? String, !path.isEmpty {
                paths.append(path)
            } else if let moduleSpecifier = resource["moduleSpecifier"] as? String, !moduleSpecifier.isEmpty {
                paths.append(moduleSpecifier)
            }
            if let family = resource["artifactFamily"] as? String, !family.isEmpty {
                families.insert(family)
            }
            if resource["ipcAugmented"] as? Bool == true {
                ipcAugmented = true
            }
        }
        compact["resourceCount"] = resources.count
        compact["resourcePaths"] = compactTraceString(paths.joined(separator: ","), maxLength: 4096)
        compact["resourceFamilies"] = families.sorted().joined(separator: ",")
        if ipcAugmented {
            compact["ipcAugmented"] = true
        }
        compact["resourcesRedacted"] = true
    }
    return compact
}

func uidlTraceSearchIndex(_ body: String) -> String {
    let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "._@/-:$"))
    let tokens = body.components(separatedBy: allowed.inverted)
    var seen = Set<String>()
    var result: [String] = []
    var totalLength = 0
    for token in tokens {
        if token.count < 2 || token.count > 220 || seen.contains(token) {
            continue
        }
        let keep = token.hasPrefix("framework-")
            || token.hasPrefix("com.vaadin.")
            || token.hasPrefix("dev.vatori.")
            || token.hasPrefix("@vaadin/")
            || token.hasPrefix("VAADIN/")
            || token.contains("flow-ipc")
            || token.contains("Flow.loadOnDemand")
            || token.contains("LoadMode")
            || token.contains("uidl")
            || token.contains("UIDL")
            || token == "LAZY"
            || token == "DYNAMIC_IMPORT"
            || token == "setViewportRange"
            || token == "scrollToIndex"
            || token == "flow-client-engine-visible"
        if !keep {
            continue
        }
        seen.insert(token)
        result.append(token)
        totalLength += token.count + 1
        if totalLength > 80_000 {
            break
        }
    }
    return result.joined(separator: ",")
}

func redactedUidlPayload(_ payload: [String: Any]) -> [String: Any] {
    var copy = compactFlowIpcTracePayload(payload)
    if let clientState = payload["clientState"] as? [String: Any] {
        copy["clientState"] = compactScalarTracePayload(clientState, maxStringLength: 256)
    }
    if let flowClientResources = payload["flowClientResources"] as? [String: Any] {
        copy["flowClientResources"] = compactResourceManifestPayload(flowClientResources)
    }
    if let componentFrontendResources = payload["componentFrontendResources"] as? [String: Any] {
        copy["componentFrontendResources"] = compactResourceManifestPayload(componentFrontendResources)
    }
    guard var uidl = payload["uidl"] as? [String: Any],
          let body = uidl["body"] as? String else {
        return copy
    }
    uidl["bodyPreview"] = compactTraceString(body, maxLength: 768)
    uidl["bodyBytes"] = body.utf8.count
    uidl["bodyRedacted"] = true
    uidl["bodySearchIndex"] = uidlTraceSearchIndex(body)
    uidl.removeValue(forKey: "body")
    copy["uidl"] = uidl
    return copy
}

func redactedSensitiveRpcValue(_ value: Any, key: String = "") -> Any {
    let normalizedKey = key.lowercased()
    if normalizedKey.contains("password") || normalizedKey.contains("secret") {
        if let stringValue = value as? String {
            return "[redacted length=\(stringValue.count)]"
        }
        return "[redacted]"
    }
    if let dictionary = value as? [String: Any] {
        var redacted: [String: Any] = [:]
        for (childKey, childValue) in dictionary {
            redacted[childKey] = redactedSensitiveRpcValue(childValue, key: childKey)
        }
        return redacted
    }
    if let array = value as? [Any] {
        return array.map { redactedSensitiveRpcValue($0, key: key) }
    }
    return value
}

func redactedEventPayload(_ payload: [String: Any]) -> [String: Any] {
    redactedSensitiveRpcValue(payload) as? [String: Any] ?? payload
}

func redactedFlowIpcEnvelope(_ object: [String: Any]) -> [String: Any] {
    if let type = object["type"] as? String,
       ["bootstrapResponse", "push", "patch", "resync"].contains(type),
       let payload = object["payload"] as? [String: Any] {
        var copy = object
        copy["payload"] = redactedUidlPayload(payload)
        return copy
    }

    if object["type"] as? String == "event",
       let payload = object["payload"] as? [String: Any] {
        var copy = object
        copy["payload"] = redactedEventPayload(payload)
        return copy
    }

    if object["type"] as? String == "resourceResponse",
       var payload = object["payload"] as? [String: Any],
       let body = payload["body"] as? String {
        var copy = object
        payload["bodyPreview"] = String(body.prefix(96))
        payload["bodyBytes"] = body.utf8.count
        payload["bodyRedacted"] = true
        payload.removeValue(forKey: "body")
        copy["payload"] = compactFlowIpcTracePayload(payload, maxStringLength: 768)
        return copy
    }

    if object["type"] as? String == "resourceResponse",
       let payload = object["payload"] as? [String: Any] {
        var copy = object
        copy["payload"] = compactFlowIpcTracePayload(payload, maxStringLength: 768)
        return copy
    }

    if object["type"] as? String == "resourceRequest",
       let payload = object["payload"] as? [String: Any] {
        var copy = object
        copy["payload"] = compactFlowIpcTracePayload(payload, maxStringLength: 768)
        return copy
    }

    if object["type"] as? String == "command",
       var payload = object["payload"] as? [String: Any],
       payload["command"] as? String == "fileTransfer.download",
       var args = payload["args"] as? [String: Any],
       let body = args["body"] as? String {
        var copy = object
        args["bodyPreview"] = String(body.prefix(32))
        args["bodyBytes"] = body.utf8.count
        args["bodyRedacted"] = true
        args.removeValue(forKey: "body")
        payload["args"] = args
        copy["payload"] = payload
        return copy
    }

    return object
}

func redactedJavaStdoutLine(_ line: String) -> String {
    guard line.hasPrefix("VFIPC1 ") else {
        return line
    }
    let raw = String(line.dropFirst(7))
    guard let data = raw.data(using: .utf8),
          let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
          let redacted = try? JSONSerialization.data(withJSONObject: redactedFlowIpcEnvelope(object)),
          let text = String(data: redacted, encoding: .utf8) else {
        return line
    }
    return "VFIPC1 \(text)"
}

struct FlowIpcHostResourceEntry {
    let sourcePath: String
    let fileURL: URL
    let mimeType: String
    let sha256: String
    let bytes: Int
    let cacheStatus: String
    let relativeImportBase: String
    let metadata: [String: Any]
}

final class FlowIpcResourceSchemeHandler: NSObject, WKURLSchemeHandler {
    static let schemeName = "vatori-resource"
    private let queue = DispatchQueue(label: "dev.vatori.desktop.flow-ipc-resource-scheme")
    private var resources: [String: FlowIpcHostResourceEntry] = [:]

    func register(urlPath: String, entry: FlowIpcHostResourceEntry) {
        queue.sync {
            resources[urlPath] = entry
        }
    }

    func webView(_ webView: WKWebView, start urlSchemeTask: WKURLSchemeTask) {
        guard let url = urlSchemeTask.request.url else {
            urlSchemeTask.didFailWithError(NSError(domain: "dev.vatori.desktop.resource-scheme",
                                                   code: 400,
                                                   userInfo: [NSLocalizedDescriptionKey: "missing resource URL"]))
            return
        }
        let urlPath = url.path
        let entry = queue.sync { resources[urlPath] }
        var requestTrace: [String: Any] = [
            "frontendResourceSchemeVersion": "flow-ipc-resource-scheme-v1_17",
            "frontendResourceSchemeName": Self.schemeName,
            "frontendResourceLoaderMode": "custom-scheme-file-backed",
            "stagingMode": "custom-scheme",
            "frontendResourceSchemeHandlerInstalled": true,
            "frontendResourceSchemeRequestObserved": true,
            "frontendResourceSchemeResponseObserved": false,
            "frontendResourceLoaderNoLocalhost": true,
            "resourceUrl": url.absoluteString,
            "resourceUrlPath": urlPath,
            "sourcePath": entry?.sourcePath ?? "",
            "mimeType": entry?.mimeType ?? "",
            "sha256": entry?.sha256 ?? "",
            "bytes": entry?.bytes ?? 0,
            "cacheStatus": entry?.cacheStatus ?? "missing",
            "relativeImportBase": entry?.relativeImportBase ?? "",
            "cleanupPolicy": "cleanup-owned-window-lifetime-file-backed-v1_17"
        ]
        if let metadata = entry?.metadata {
            for (key, value) in metadata {
                requestTrace[key] = value
            }
        }
        trace("recv", "resourceLoad", compactResourceLoadTrace(requestTrace))

        guard let entry else {
            let response = URLResponse(url: url,
                                       mimeType: "text/plain",
                                       expectedContentLength: 0,
                                       textEncodingName: "utf-8")
            urlSchemeTask.didReceive(response)
            urlSchemeTask.didFailWithError(NSError(domain: "dev.vatori.desktop.resource-scheme",
                                                   code: 404,
                                                   userInfo: [NSLocalizedDescriptionKey: "resource not registered"]))
            return
        }

        do {
            let data = try Data(contentsOf: entry.fileURL)
            let headers = [
                "Content-Type": entry.mimeType,
                "Content-Length": String(data.count),
                "Cache-Control": "no-store",
                "Access-Control-Allow-Origin": "*",
                "Cross-Origin-Resource-Policy": "cross-origin"
            ]
            if let response = HTTPURLResponse(url: url,
                                              statusCode: 200,
                                              httpVersion: "HTTP/1.1",
                                              headerFields: headers) {
                urlSchemeTask.didReceive(response)
            } else {
                let response = URLResponse(url: url,
                                           mimeType: entry.mimeType,
                                           expectedContentLength: data.count,
                                           textEncodingName: "utf-8")
                urlSchemeTask.didReceive(response)
            }
            urlSchemeTask.didReceive(data)
            urlSchemeTask.didFinish()
            var responseTrace: [String: Any] = [
                "frontendResourceSchemeVersion": "flow-ipc-resource-scheme-v1_17",
                "frontendResourceSchemeName": Self.schemeName,
                "frontendResourceLoaderMode": "custom-scheme-file-backed",
                "stagingMode": "custom-scheme",
                "frontendResourceSchemeHandlerInstalled": true,
                "frontendResourceSchemeRequestObserved": true,
                "frontendResourceSchemeResponseObserved": true,
                "frontendResourceLoaderNoLocalhost": true,
                "resourceUrl": url.absoluteString,
                "resourceUrlPath": urlPath,
                "sourcePath": entry.sourcePath,
                "mimeType": entry.mimeType,
                "sha256": entry.sha256,
                "bytes": data.count,
                "cacheStatus": entry.cacheStatus,
                "relativeImportBase": entry.relativeImportBase,
                "cleanupPolicy": "cleanup-owned-window-lifetime-file-backed-v1_17",
                "executionStatus": "served"
            ]
            for (key, value) in entry.metadata {
                responseTrace[key] = value
            }
            trace("send", "resourceLoad", compactResourceLoadTrace(responseTrace))
        } catch {
            urlSchemeTask.didFailWithError(error)
            var failureTrace: [String: Any] = [
                "frontendResourceSchemeVersion": "flow-ipc-resource-scheme-v1_17",
                "frontendResourceSchemeName": Self.schemeName,
                "frontendResourceLoaderMode": "custom-scheme-file-backed",
                "stagingMode": "custom-scheme",
                "frontendResourceSchemeHandlerInstalled": true,
                "frontendResourceSchemeRequestObserved": true,
                "frontendResourceSchemeResponseObserved": false,
                "frontendResourceLoaderNoLocalhost": true,
                "resourceUrl": url.absoluteString,
                "resourceUrlPath": urlPath,
                "sourcePath": entry.sourcePath,
                "mimeType": entry.mimeType,
                "sha256": entry.sha256,
                "bytes": entry.bytes,
                "cacheStatus": entry.cacheStatus,
                "relativeImportBase": entry.relativeImportBase,
                "cleanupPolicy": "cleanup-owned-window-lifetime-file-backed-v1_17",
                "browserError": error.localizedDescription,
                "executionStatus": "serve-failed"
            ]
            for (key, value) in entry.metadata {
                failureTrace[key] = value
            }
            trace("send", "resourceLoad", compactResourceLoadTrace(failureTrace))
        }
    }

    func webView(_ webView: WKWebView, stop urlSchemeTask: WKURLSchemeTask) {
    }
}

final class LineReader {
    private var buffer = Data()
    private let onLine: (String) -> Void

    init(onLine: @escaping (String) -> Void) {
        self.onLine = onLine
    }

    func append(_ data: Data) {
        buffer.append(data)
        while let range = buffer.firstRange(of: Data([0x0A])) {
            let lineData = buffer.subdata(in: buffer.startIndex..<range.lowerBound)
            buffer.removeSubrange(buffer.startIndex..<range.upperBound)
            if let line = String(data: lineData, encoding: .utf8) {
                onLine(line.trimmingCharacters(in: .newlines))
            }
        }
    }
}

final class JavaSidecar {
    private let config: HostConfig
    private let onApplicationURL: (URL) -> Void
    private let onFlowIpcEnvelope: (String, [String: Any]) -> Void
    private var process: Process?
    private var stdinPipe: Pipe?
    private var stdoutPipe: Pipe?
    private var stderrPipe: Pipe?

    init(config: HostConfig,
         onApplicationURL: @escaping (URL) -> Void,
         onFlowIpcEnvelope: @escaping (String, [String: Any]) -> Void) {
        self.config = config
        self.onApplicationURL = onApplicationURL
        self.onFlowIpcEnvelope = onFlowIpcEnvelope
    }

    func start() {
        let modulePom = "\(config.module)/pom.xml"
        guard FileManager.default.fileExists(atPath: modulePom) else {
            trace("send", "error", [
                "code": "moduleNotFound",
                "message": "Module pom not found: \(modulePom)"
            ])
            NSApp.terminate(nil)
            return
        }

        let process = Process()
        process.currentDirectoryURL = URL(fileURLWithPath: config.repoRoot)
        let directJar = config.transport == "flow-ipc" ? runnableJar(in: config.module) : nil
        if let directJar {
            process.executableURL = URL(fileURLWithPath: javaExecutable())
            process.arguments = [
                "-jar",
                directJar
            ]
        } else {
            process.executableURL = URL(fileURLWithPath: config.mavenExecutable)
            let mavenMode = ProcessInfo.processInfo.environment["VAADIN_DESKTOP_MAVEN_OFFLINE"] == "1" ? "-o" : "-U"
            process.arguments = [
                mavenMode,
                "-Dmaven.repo.local=\(config.mavenRepo)",
                "-f",
                modulePom,
                "spring-boot:run"
            ]
        }

        var environment = ProcessInfo.processInfo.environment
        environment["VAADIN_DESKTOP_HOST"] = config.transport == "flow-ipc" ? "flow-ipc" : "headless"
        environment["VAADIN_DESKTOP_TRANSPORT"] = config.transport
        environment["VAADIN_DESKTOP_NATIVE_BRIDGE"] = "host-protocol"
        environment["VAADIN_DESKTOP_HOST_PROTOCOL"] = "stdout-v0"
        environment["VAADIN_DESKTOP_REPO_ROOT"] = config.repoRoot
        environment["VAADIN_DESKTOP_MODULE"] = config.module
        process.environment = environment

        let stdinPipe = Pipe()
        let stdoutPipe = Pipe()
        let stderrPipe = Pipe()
        process.standardInput = stdinPipe
        process.standardOutput = stdoutPipe
        process.standardError = stderrPipe
        self.stdinPipe = stdinPipe
        self.stdoutPipe = stdoutPipe
        self.stderrPipe = stderrPipe
        self.process = process

        let stdoutReader = LineReader { [weak self] line in
            self?.handleStdout(line)
        }
        stdoutPipe.fileHandleForReading.readabilityHandler = { handle in
            stdoutReader.append(handle.availableData)
        }

        stderrPipe.fileHandleForReading.readabilityHandler = { handle in
            let data = handle.availableData
            if !data.isEmpty, let text = String(data: data, encoding: .utf8) {
                FileHandle.standardError.write(("[java:err] \(text)").data(using: .utf8)!)
            }
        }

        process.terminationHandler = { process in
            trace("recv", "sidecar.exit", [
                "status": process.terminationStatus,
                "reason": process.terminationReason.rawValue
            ])
            if process.terminationStatus != 0 {
                DispatchQueue.main.async {
                    NSApp.terminate(nil)
                }
            }
        }

        trace("send", "launch.sidecar", [
            "command": directJar == nil ? "\(config.mavenExecutable) spring-boot:run" : "\(javaExecutable()) -jar",
            "modulePom": modulePom,
            "jar": directJar ?? "",
            "nativeBridge": "host-protocol",
            "transport": config.transport
        ])

        do {
            try process.run()
        } catch {
            trace("send", "error", [
                "code": "sidecarStartFailed",
                "message": error.localizedDescription
            ])
            NSApp.terminate(nil)
        }
    }

    func terminate() {
        if config.transport == "flow-ipc" {
            trace("send", "shutdown", [
                "target": "java-sidecar",
                "transport": "flow-ipc",
                "reason": "host-terminate"
            ])
            sendFlowIpc("{\"version\":\"flow-ipc-v1\",\"type\":\"shutdown\",\"id\":\"shutdown\",\"correlationId\":\"shutdown\",\"sessionId\":\"flow-ipc-session\",\"uiId\":\"main\",\"route\":\"\",\"payload\":{},\"error\":null,\"timestamp\":0}")
        }
        stdoutPipe?.fileHandleForReading.readabilityHandler = nil
        stderrPipe?.fileHandleForReading.readabilityHandler = nil
        if let process, process.isRunning {
            trace("send", "shutdown.sidecar", [:])
            process.terminate()
        }
    }

    func sendFlowIpc(_ envelope: String) {
        guard let stdinPipe else {
            trace("send", "flow-ipc.sidecarWrite", [
                "target": "java-sidecar",
                "status": "missing-stdin-pipe"
            ])
            return
        }
        let line = "VFIPC1 \(envelope)\n"
        if let data = line.data(using: .utf8) {
            stdinPipe.fileHandleForWriting.write(data)
            trace("send", "flow-ipc.sidecarWrite", [
                "target": "java-sidecar",
                "status": "written",
                "bytes": data.count
            ])
        }
    }

    private func javaExecutable() -> String {
        if let javaHome = ProcessInfo.processInfo.environment["JAVA_HOME"], !javaHome.isEmpty {
            let candidate = "\(javaHome)/bin/java"
            if FileManager.default.isExecutableFile(atPath: candidate) {
                return candidate
            }
        }
        return "/usr/bin/java"
    }

    private func runnableJar(in modulePath: String) -> String? {
        let targetPath = "\(modulePath)/target"
        guard let entries = try? FileManager.default.contentsOfDirectory(atPath: targetPath) else {
            return nil
        }
        let jars = entries
            .filter { entry in
                entry.hasSuffix(".jar")
                    && !entry.hasSuffix(".jar.original")
                    && !entry.hasSuffix("-sources.jar")
                    && !entry.hasSuffix("-javadoc.jar")
            }
            .sorted()
        guard let jar = jars.first else {
            return nil
        }
        return "\(targetPath)/\(jar)"
    }

    private func handleStdout(_ line: String) {
        print("[java] \(redactedJavaStdoutLine(line))")
        fflush(stdout)

        if line.hasPrefix("VDP1 ") {
            handleHostProtocolEnvelope(String(line.dropFirst(5)))
        }

        if line.hasPrefix("VFIPC1 ") {
            handleFlowIpcEnvelope(String(line.dropFirst(7)))
        }

        if line.hasPrefix("Application URL: ") {
            let text = String(line.dropFirst("Application URL: ".count)).trimmingCharacters(in: .whitespacesAndNewlines)
            if let url = URL(string: text) {
                DispatchQueue.main.async {
                    self.onApplicationURL(url)
                }
            }
        }
    }

    private func handleFlowIpcEnvelope(_ envelope: String) {
        guard let data = envelope.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            trace("send", "error", [
                "code": "invalidFlowIpcEnvelope",
                "raw": envelope
            ])
            return
        }
        DispatchQueue.main.async {
            self.onFlowIpcEnvelope(envelope, object)
        }
    }

    private func handleHostProtocolEnvelope(_ envelope: String) {
        guard let data = envelope.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            trace("send", "error", [
                "code": "invalidJavaEnvelope",
                "raw": envelope
            ])
            return
        }

        let type = object["type"] as? String ?? "unknown"
        trace("recv", type, [
            "source": "java-sidecar",
            "envelope": object
        ])

        if type == "command",
           let payload = object["payload"] as? [String: Any],
           let command = payload["command"] as? String {
            trace("send", "capabilityResult", [
                "command": command,
                "mode": "swift-host-scaffold",
                "result": "traced"
            ])
        }
    }
}

final class WebViewHost: NSObject, NSApplicationDelegate, NSWindowDelegate, WKNavigationDelegate, WKScriptMessageHandler {
    private let config: HostConfig
    private let capabilityManifest: CapabilityManifest
    private let resourceSchemeHandler = FlowIpcResourceSchemeHandler()
    private var sidecar: JavaSidecar?
    private var window: NSWindow?
    private var webView: WKWebView?
    private var didOpenWindow = false
    private var fileDialogInFlight = false
    private var fileTransferPanelInFlight = false
    private var hostResourceStageCache: Set<String> = []

    init(config: HostConfig) {
        self.config = config
        self.capabilityManifest = CapabilityManifest.load(module: config.module)
    }

    func applicationDidFinishLaunching(_ notification: Notification) {
        trace("recv", "launch", [
            "host": "swift-appkit-wkwebview",
            "module": config.module,
            "compatibilityMode": config.transport != "flow-ipc",
            "transport": config.transport
        ])
        trace("send", "ready", [
            "host": "swift-appkit-wkwebview",
            "protocol": config.transport == "flow-ipc" ? "flow-ipc-v1" : "host-protocol-v0",
            "compatibilityMode": config.transport != "flow-ipc"
        ])
        if config.transport == "flow-ipc" {
            trace("recv", "capabilityManifest", capabilityManifest.tracePayload())
        }

        let sidecar = JavaSidecar(config: config) { [weak self] url in
            self?.openWindow(url: url)
        } onFlowIpcEnvelope: { [weak self] raw, object in
            self?.handleFlowIpcEnvelope(raw, object)
        }
        self.sidecar = sidecar
        sidecar.start()
    }

    func applicationWillTerminate(_ notification: Notification) {
        sidecar?.terminate()
    }

    private func openWindow(url: URL) {
        guard !didOpenWindow else {
            return
        }
        didOpenWindow = true

        trace("send", "window.create", [
            "label": "main",
            "url": url.absoluteString,
            "mode": "compatibility-http"
        ])

        let contentRect = NSRect(x: 0, y: 0, width: config.width, height: config.height)
        let window = NSWindow(
            contentRect: contentRect,
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered,
            defer: false)

        let configuration = WKWebViewConfiguration()
        configuration.preferences.javaScriptCanOpenWindowsAutomatically = true
        let webView = WKWebView(frame: contentRect, configuration: configuration)
        webView.navigationDelegate = self
        webView.autoresizingMask = [.width, .height]

        window.title = config.title
        window.contentView = webView
        window.delegate = self
        window.isReleasedWhenClosed = false
        window.sharingType = .readOnly
        window.level = .normal
        window.collectionBehavior = [.fullScreenPrimary]
        window.center()
        showWindow(window)

        self.window = window
        self.webView = webView

        webView.load(URLRequest(url: url))
        trace("recv", "window.ready", ["label": "main"])
    }

