        if extendedFlowIpcVerification {
            DispatchQueue.main.asyncAfter(deadline: .now() + 9.0) {
                self.inspectWebView(webView)
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 16.0) {
                self.inspectWebView(webView)
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + 24.0) {
