          flowClientEnginePromotionRetryAttempts += 1;
          refreshFlowClientEngineDiagnostics();
          if (!window.VaadinDesktopIpcDiagnostics.flowClientEngineVisibleOwner
              && flowClientEnginePromotionRetryAttempts < 24) {
