      function prepareRichTextEditorBehaviorProbe(kind, element) {
        if (!element) {
          return;
        }
        const editor = element._editor || null;
        const marker = autoFrameworkRichTextEditorBehaviorMarker;
        try {
          if (editor && typeof editor.setText === 'function'
              && (kind === 'selection' || kind === 'toolbar' || kind === 'keyboard')) {
            editor.setText(marker, 'api');
          }
          if (editor && typeof editor.setSelection === 'function'
              && (kind === 'selection' || kind === 'toolbar' || kind === 'keyboard')) {
            editor.setSelection(0, 8, 'user');
          }
          if (editor && typeof editor.formatText === 'function'
              && (kind === 'toolbar' || kind === 'keyboard')) {
            editor.formatText(0, 8, 'bold', true, 'user');
          }
          if (kind === 'toolbar' && element.shadowRoot) {
            const boldButton = element.shadowRoot.querySelector(
              '[part~="toolbar-button-bold"], [part="toolbar-button-bold"], button[aria-label="Bold"]');
            if (boldButton && typeof boldButton.click === 'function') {
              window.VaadinDesktopIpcDiagnostics.frameworkRichTextEditorBehaviorMatrixToolbarRendered = true;
              boldButton.click();
            }
          }
          if (kind === 'keyboard') {
            const keyboardTarget = editor && editor.root ? editor.root : element;
            if (keyboardTarget && typeof keyboardTarget.dispatchEvent === 'function') {
              keyboardTarget.dispatchEvent(new KeyboardEvent('keydown', {
                key: 'b',
                code: 'KeyB',
                metaKey: true,
                bubbles: true,
                composed: true
              }));
            }
          }
          if (kind === 'delta') {
            element.value = autoFrameworkRichTextEditorBehaviorDelta;
            try {
              element.htmlValue = autoFrameworkRichTextEditorBehaviorHtml;
            } catch (_) {
              // Some RichTextEditor versions expose htmlValue as read-only.
            }
          }
        } catch (error) {
          window.VaadinDesktopIpcDiagnostics.frameworkAppFailureReason =
            error && error.message ? error.message : String(error);
        }
      }

