      function startAutoFrameworkUpdatePolling() {
        if (!window.__VAADIN_DESKTOP_FLOW_IPC_AUTO_FRAMEWORK_UPDATE__ || autoFrameworkUpdateInterval) {
          return;
        }
        autoFrameworkUpdateInterval = setInterval(() => {
