      function flowTreeTextById(node, id) {
        if (!node) {
          return '';
        }
        if (node.id === id && typeof node.text === 'string') {
          return node.text;
        }
        if (Array.isArray(node.children)) {
          for (const child of node.children) {
            const text = flowTreeTextById(child, id);
            if (text) {
              return text;
            }
          }
        }
        return '';
      }

